CREATE TABLE orders AS
  SELECT i AS order_id, 'A' AS store FROM range(1, 41) t(i)
  UNION ALL
  SELECT i, 'B' FROM range(101, 103) t(i);
CREATE TABLE refunds AS SELECT * FROM (VALUES
  (1, 'A'), (2, 'A'), (3, 'A'), (4, 'A'), (101, 'B')
) AS t(order_id, store);

