en.bien_sql:
SELECT name
FROM people p
WHERE NOT EXISTS (
  SELECT 1 FROM alibis a WHERE a.name = p.name
);
-- or, filtering the NULL out of the list itself:
WHERE name NOT IN (
  SELECT name FROM alibis WHERE name IS NOT NULL
)

en.bien_sql_alt:
