en.datos:
CREATE TABLE transactions AS SELECT * FROM (VALUES
  (DATE '2026-04-01', 100.0),
  (DATE '2026-04-02', 50.0),
  (DATE '2026-04-02', 30.0),
  (DATE '2026-04-03', 20.0)
) AS t(date, amount);

en.bien_sql:
SELECT date, amount,
       sum(amount) OVER (
         ORDER BY date
         ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS balance
FROM transactions;

